#include <bits/stdc++.h>
using namespace std;using G=vector<unsigned>; mt19937 rng(225);
bool weak(const G&a){for(int v=0;v<a.size();v++){bool ok=0;for(int x=0;x<a.size()&&!ok;x++)if(a[v]>>x&1)for(int y=x+1;y<a.size();y++)if((a[v]>>y&1)&&!(a[x]>>y&1)&&__builtin_popcount(a[x]&a[y])==1){ok=1;break;}if(!ok)return 0;}return 1;}
void edge(G&a,int x,int y){a[x]^=1u<<y;a[y]^=1u<<x;}
int nodes;
bool subweak(G&a,int start=0){if(++nodes>200000)return false;if(weak(a))return true;int n=a.size();for(int i=start;i<n*n;i++){int x=i/n,y=i%n;if(x>=y||!(a[x]>>y&1)||__builtin_popcount(a[x])<=2||__builtin_popcount(a[y])<=2)continue;edge(a,x,y);if(subweak(a,i+1)){edge(a,x,y);return true;}edge(a,x,y);if(nodes>200000)return false;}return false;}
int main(){for(int n=6;n<=18;n++){int tested=0,passes=0,unknown=0;for(int z=0;z<2500;z++){G a(n);for(int i=0;i<n;i++)edge(a,i,(i+1)%n);vector<pair<int,int>> pp;for(int i=0;i<n;i++)for(int j=i+1;j<n;j++)if(!(a[i]>>j&1))pp.push_back({i,j});shuffle(pp.begin(),pp.end(),rng);int steps=rng()%(pp.size()+1);for(int k=0;k<steps;k++){auto[x,y]=pp[k];edge(a,x,y);if(!weak(a))edge(a,x,y);}if(!weak(a))abort();pair<int,int> best={999,999};vector<int> vs;for(int v=0;v<n;v++){int d2=0;for(int j=0;j<n;j++)if((a[v]>>j&1)&&__builtin_popcount(a[j])==2)d2++;pair<int,int>key={d2,__builtin_popcount(a[v])};if(key<best){best=key;vs.clear();}if(key==best)vs.push_back(v);}bool ok=0,cap=0;int ops=0;for(int v:vs){G b=a;for(int j=0;j<n;j++)if(b[v]>>j&1)edge(b,v,j);vector<pair<int,int>> fills;unsigned need=0;for(int i=0;i<n;i++)if(a[v]>>i&1){if(__builtin_popcount(b[i])<2)need|=1u<<i;for(int j=i+1;j<n;j++)if((a[v]>>j&1)&&!(b[i]>>j&1))fills.push_back({i,j});}int minfill=999;vector<unsigned> masks;if(fills.size()>20){cap=1;continue;}for(unsigned m=0;m<(1u<<fills.size());m++){int c=__builtin_popcount(m);if(c>minfill)continue;unsigned covered=0;for(int i=0;i<fills.size();i++)if(m>>i&1)covered|=(1u<<fills[i].first)|(1u<<fills[i].second);if((covered&need)!=need)continue;if(c<minfill){minfill=c;masks.clear();}masks.push_back(m);}for(auto m:masks){G c=b;for(int i=0;i<fills.size();i++)if(m>>i&1)edge(c,fills[i].first,fills[i].second);G d;for(int i=0;i<n;i++)if(i!=v){unsigned u=0;int k=0;for(int j=0;j<n;j++)if(j!=v){if(c[i]>>j&1)u|=1u<<k;k++;}d.push_back(u);}nodes=0;ops++;if(subweak(d)){ok=1;break;}if(nodes>200000)cap=1;}if(ok)break;}tested++;if(ok)passes++;else if(cap)unknown++;else{cout<<"FAIL n="<<n<<" z="<<z<<" adjacency";for(auto u:a)cout<<" "<<u;cout<<" operations="<<ops<<endl;return 0;}}cout<<"n="<<n<<" tested="<<tested<<" passed="<<passes<<" unknown="<<unknown<<endl;}}
